func declarations(name string,raw []byte)map[string]string{set:=token.NewFileSet();f,e:=parser.ParseFile(set,name,raw,0);if e!=nil{panic(e)};out:=map[string]string{};emit:=func(k string,n ast.Node){var b bytes.Buffer;if e:=format.Node(&b,set,n);e!=nil{panic(e)};out[k]=b.String()};for _,d:=range f.Decls{switch n:=d.(type){case *ast.FuncDecl:emit("func "+n.Name.Name,n);case *ast.GenDecl:for _,s:=range n.Specs{switch v:=s.(type){case *ast.TypeSpec:emit("type "+v.Name.Name,v);case *ast.ValueSpec:for _,id:=range v.Names{emit(n.Tok.String()+" "+id.Name,v)}}}}};return out}
func main(){names:=[]string{"internal/execution/adapters/codex/history.go","internal/execution/adapters/codex/history_binding.go","internal/execution/backend/backend.go"};allowed:=map[string]bool{"func CheckHistory":true,"func ReadMetadata":true,"func ReadPage":true,"func MapHistoryTurn":true,"func conversationItemKey":true,"func cloneStringMap":true,"func UserAgent":true,"func NativeHome":true,"type HistoryPage":true,"const MaxHistoryCursorBytes":true,"func Event":true,"type ExecutionProbe":true,"type ExecutionBackend":true,"type ExecutionStopper":true};old,e:=exec.Command("git","show","HEAD:internal/execution/adapters/codex/conversation_adapter.go").Output();if e!=nil{panic(e)};limit:=declarations("adapter.go",old)["const maxConversationCursorBytes"];count,types:=0,0;removed:=map[string][]string{};for _,name:=range names{raw,e:=os.ReadFile(".evidence/history-adapter-cleanup/base/"+name);if e!=nil{panic(e)};before:=declarations(name,raw);raw,e=os.ReadFile(name);if e!=nil{panic(e)};after:=declarations(name,raw);for key,value:=range after{if key=="const maxConversationCursorBytes"&&value==limit{continue};if value!=before[key]{panic("retained declaration changed: "+name+":"+key)};count++;if len(key)>5&&key[:5]=="type "{types++}};for key:=range before{if _,exists:=after[key];!exists{if !allowed[key]{panic("unexpected removal: "+name+":"+key)};removed[name]=append(removed[name],key)}}};oldPhase,e:=exec.Command("git","show","HEAD:internal/execution/evidence/conversation.go").Output();if e!=nil{panic(e)};phaseRaw,e:=os.ReadFile("internal/execution/evidence/message_phase.go");if e!=nil{panic(e)};phaseBefore:=declarations("old-phase.go",oldPhase);phaseAfter:=declarations("message_phase.go",phaseRaw);if len(phaseAfter)!=4{panic("phase declaration count changed")};for k,v:=range phaseAfter{if phaseBefore[k]!=v{panic("shared phase declaration changed: "+k)}};value:=map[string]any{"shared_phase_declarations_moved_identical":4,"identical_retained_declarations":count,"identical_retained_types":types,"modified_retained_declarations":[]string{},"removed_declarations_in_shared_files":removed,"added_declaration":"original maxConversationCursorBytes=64<<10 moved unchanged from retired adapter"};raw,_:=json.MarshalIndent(value,"","  ");if e:=os.WriteFile(".evidence/history-adapter-cleanup/retained-audit.json",raw,0600);e!=nil{panic(e)};fmt.Println(string(raw))}
